# name: example_target_yes_rate
# description: Yes rate on trials whose target is itself one of the shown examples; observed below null means people endorse the examples themselves less than the model (which treats examples as near-certain members) predicts.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce")
    t = df["target"].astype(int).to_numpy()
    is_ex = (ex.to_numpy() == t[:, None]).any(axis=1)
    if is_ex.sum() == 0:
        return 0.0
    return float(df["rating"].to_numpy()[is_ex].mean())

# name: cell_extremity_fraction
# description: Fraction of (set, target) cells whose mean yes rate is <= 0.15 or >= 0.85; observed above null means human judgments are more all-or-none (the model's predictions are too graded/intermediate), below null means they are more graded than the model.
def test_statistic(df):
    m = df.groupby(["number_set", "target"])["rating"].mean().to_numpy()
    if len(m) == 0:
        return 0.0
    return float(np.mean((m <= 0.15) | (m >= 0.85)))

# name: trial_index_drift
# description: Pearson correlation between trial_index and rating across all trials; observed differing from null (near 0, the model has no time dependence) means yes-rate drifts over the session (positive = more yes later, negative = fewer).
def test_statistic(df):
    x = df["trial_index"].astype(float).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    if x.std() == 0 or y.std() == 0:
        return 0.0
    return float(np.corrcoef(x, y)[0, 1])
